from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify separate groups of parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            if current_group:
                groups.append(current_group)
            current_group = "("
        elif char == ")":
            current_group += ")"
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced by counting the number of open and close parentheses
    def is_balanced(group):
        count = 0
        for char in group:
            if char == "(":
                count += 1
            elif char == ")":
                count -= 1
            if count < 0:
                return False
        return count == 0

    # Step 4: Store each separate group in a list and return the list
    result = [group for group in groups if is_balanced(group)]

    return result

